package net.civeira.phylax.feature.access.usergroupmembership.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.usergroupmembership.domain.UserGroupMembership;
import net.civeira.phylax.feature.access.usergroupmembership.domain.valueobject.GroupsVO;

class GroupsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of groups of user group membership")
  void test_groups_value_holder_assign_plain_value() {
    Object holder = new Object();
    GroupsValueHolder<Object> value = new GroupsValueHolder<>(holder);
    Assertions.assertSame(holder, value.groups("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getGroupsValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getGroups().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.groupsNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getGroupsValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getGroups().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of groups of user group membership")
  void test_groups_value_holder_assign_value_object() {
    Object holder = new Object();
    GroupsValueHolder<Object> value = new GroupsValueHolder<>(holder);
    GroupsVO vo = GroupsVO.from("one");
    Assertions.assertFalse(value.getGroupsValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.groups(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getGroupsValue().orElseThrow());
    Assertions.assertSame(holder, value.groups(Optional.empty()));
    Assertions.assertFalse(value.getGroupsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.groups(Optional.of(vo)));
    Assertions.assertSame(vo, value.getGroupsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of groups of user group membership against the original")
  void test_groups_value_holder_read() {
    Object holder = new Object();
    GroupsValueHolder<Object> value = new GroupsValueHolder<>(holder);
    GroupsVO vo = GroupsVO.from("one");
    GroupsVO other = GroupsVO.from("one");
    UserGroupMembership original = Mockito.mock(UserGroupMembership.class);
    Mockito.when(original.getGroupsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readGroups(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readGroups(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.groups(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readGroups(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readGroups(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of groups of user group membership")
  void test_groups_value_holder_unset() {
    Object holder = new Object();
    GroupsValueHolder<Object> value = new GroupsValueHolder<>(holder);
    GroupsVO vo = GroupsVO.from("one");
    value.groups(vo);
    Assertions.assertSame(holder, value.unsetGroupsIfMatches("groups_other"));
    Assertions.assertTrue(value.getGroupsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetGroupsIfMatches("groups"));
    Assertions.assertFalse(value.getGroupsValue().isPresent(),
        "The field name must clear the value");
    value.groups(vo);
    Assertions.assertSame(holder, value.unsetGroups());
    Assertions.assertFalse(value.getGroupsValue().isPresent(), "Unset must clear the value");
  }
}
